// This file is generated by AI.

// 预览全屏的窗口侧处理: 把一次 `fullscreenchange` 折算成"窗口要不要动、怎么动"。
//
// 为什么需要它: 引擎底栏的"全屏"按钮走页面 Fullscreen API, iframe 获批后会成为顶层文档的
// 全屏元素; 而 Windows 上 Tauri 自己就会把"webview 里有全屏元素"映射成窗口全屏 (见
// tauri-runtime-wry 的 `add_ContainsFullScreenElementChanged`), 所以这里的动作在 Windows 上
// 基本是幂等的重复调用, 在其它平台才真正起作用 —— 那里没有内置映射。
//
// 真正要补的是"最大化窗口 + 无边框全屏"这个组合: tao 进入全屏时不会清掉最大化状态, 客户端区
// 停在任务栏之上的工作区大小, 底下就留下一条任务栏高的黑边 (tauri-apps/tao#1087 的脚注 [1]
// 说的正是 `{ decorations: false, fullscreen: true, maximized: true }`)。补正只能让窗口在
// **进入全屏的那一刻**不是最大化: 先撤销已经套上的窗口全屏, 再离开最大化, 最后从普通窗口重新
// 进全屏; 退出全屏时再把最大化还原回去。

/** 一次 `fullscreenchange` 之后, 窗口这边要做的唯一一件事。 */
export type PreviewFullscreenAction =
  | { kind: 'none' }
  | { kind: 'enter-fullscreen' }
  | { kind: 'leave-fullscreen' }
  | { kind: 'correct-maximized' }
  | { kind: 'restore-maximized' };

/** 上一次算出来的状态。 */
export interface PreviewFullscreenStatus {
  /** 预览 iframe 现在是不是全屏元素 */
  mirrored: boolean;
  /** 是否为了让全屏生效而取消过最大化 (退出时要还原) */
  corrected: boolean;
}

export interface PreviewFullscreenTransition extends PreviewFullscreenStatus {
  action: PreviewFullscreenAction;
}

/**
 * 窗口接口。
 *
 * Tauri 的 `Window` 结构上就满足它, 这里单独写出来是为了能注入假实现, 断言动作与顺序。
 */
export interface PreviewFullscreenWindow {
  setFullscreen(value: boolean): Promise<void>;
  unmaximize(): Promise<void>;
  maximize(): Promise<void>;
}

/**
 * 折算状态与动作。
 *
 * `windowWasMaximized` 必须是**进入全屏之前**的窗口形态: 全屏那一次 resize 本身就带着我们要修
 * 的形态变化, 拿它当"用户想要的窗口样子"就永远补不上 (见 `PreviewPanel` 里记录它的地方)。
 */
export function previewFullscreenTransition(
  previous: PreviewFullscreenStatus,
  input: { fullscreenActive: boolean; windowWasMaximized: boolean }
): PreviewFullscreenTransition {
  // 状态没变 (同一个状态下的重复事件) 什么都不做
  if (input.fullscreenActive === previous.mirrored) {
    return { ...previous, action: { kind: 'none' } };
  }

  if (input.fullscreenActive) {
    return input.windowWasMaximized
      ? { mirrored: true, corrected: true, action: { kind: 'correct-maximized' } }
      : { mirrored: true, corrected: false, action: { kind: 'enter-fullscreen' } };
  }

  return {
    mirrored: false,
    corrected: false,
    action: previous.corrected ? { kind: 'restore-maximized' } : { kind: 'leave-fullscreen' },
  };
}

/**
 * 执行动作。
 *
 * 两个补正动作的顺序都不能换, 而且第一步都是先退出窗口全屏:
 *
 * * `correct-maximized`: 退出全屏后窗口回到最大化, 这时 `unmaximize()` 才走 `SW_RESTORE` 而不会
 *   把全屏一起缩没 (tao#1087 的第 4 步就是那个现象), 之后从普通窗口重新进全屏才不会留黑边;
 * * `restore-maximized`: Tauri 可能已经自己退过窗口全屏, 重复调用是幂等的; 先退再最大化, 才能
 *   避免它随后的"还原窗口位置"把最大化又抹掉。
 */
export async function applyPreviewFullscreenAction(
  win: PreviewFullscreenWindow,
  action: PreviewFullscreenAction
): Promise<void> {
  switch (action.kind) {
    case 'none':
      return;
    case 'enter-fullscreen':
      await win.setFullscreen(true);
      return;
    case 'leave-fullscreen':
      await win.setFullscreen(false);
      return;
    case 'correct-maximized':
      await win.setFullscreen(false);
      await win.unmaximize();
      await win.setFullscreen(true);
      return;
    case 'restore-maximized':
      await win.setFullscreen(false);
      await win.maximize();
      return;
  }
}
